BEGIN;
CREATE FUNCTION pg_temp.expect(label text,ok boolean) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF NOT coalesce(ok,false) THEN RAISE EXCEPTION 'FAIL %',label;END IF;RAISE NOTICE 'PASS %',label;END$$;
CREATE FUNCTION pg_temp.reject(label text,statement text) RETURNS void LANGUAGE plpgsql AS $$DECLARE rejected boolean:=false;BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN rejected:=true;END;PERFORM pg_temp.expect(label,rejected);END$$;
CREATE TEMP TABLE f(o uuid,o2 uuid,a uuid,s uuid,x uuid,v uuid,v2 uuid,d uuid,stamp timestamptz);
INSERT INTO f SELECT gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),NULL,clock_timestamp()-interval '30 minutes';
INSERT INTO public.vihem_organisations(id,name,slug) SELECT o,'GPS QA','gps-'||o FROM f UNION ALL SELECT o2,'GPS Other','gps-'||o2 FROM f;
INSERT INTO public.vihem_module_registry(module_key,name,description,category) VALUES('fleet_management','Fleet','QA','operations') ON CONFLICT DO NOTHING;
INSERT INTO public.vihem_organisation_modules(organisation_id,module_key,enabled) SELECT o,'fleet_management',true FROM f UNION ALL SELECT o2,'fleet_management',true FROM f;
INSERT INTO auth.users(id,email) SELECT a,a||'@example.invalid' FROM f UNION ALL SELECT s,s||'@example.invalid' FROM f UNION ALL SELECT x,x||'@example.invalid' FROM f;
INSERT INTO public.vihem_profiles(id,organisation_id,name,email,role,active) SELECT a,o,'GPS Admin',a||'@example.invalid','admin',true FROM f UNION ALL SELECT s,o,'GPS Staff',s||'@example.invalid','staff',true FROM f UNION ALL SELECT x,o2,'GPS Other',x||'@example.invalid','admin',true FROM f ON CONFLICT(id) DO UPDATE SET organisation_id=excluded.organisation_id,role=excluded.role,active=true;
INSERT INTO public.vihem_fleet_vehicles(id,organisation_id,name,current_odometer,odometer_unit) SELECT v,o,'Synthetic GPS',2214,'mil' FROM f UNION ALL SELECT v2,o2,'Other GPS',0,'km' FROM f;
GRANT ALL ON f TO authenticated,service_role;
SELECT set_config('request.jwt.claim.sub',a::text,true) FROM f;
SET LOCAL ROLE authenticated;
UPDATE f SET d=public.vihem_fleet_pair_device(v,'990000000000099','FMC003','QA');
SELECT pg_temp.expect('pair retry is idempotent',public.vihem_fleet_pair_device(v,'990000000000099','FMC003','QA')=d) FROM f;
SELECT pg_temp.reject('cross organisation vehicle denied',format('SELECT public.vihem_fleet_pair_device(%L,%L,%L,%L)',v2,'990000000000099','FMC003','QA')) FROM f;
SELECT pg_temp.reject('API key not exposed','SELECT api_key FROM public.vihem_fleet_telematics_devices');
SELECT pg_temp.reject('organisation admin cannot self-provision',format('SELECT public.vihem_fleet_provision_device(%L,%L,%L,%L,%L)',d,o,v,'990000000000099','Synthetic device verification')) FROM f;
SELECT pg_temp.reject('authenticated cannot ingest',format('SELECT public.vihem_fleet_ingest_position(%L::jsonb)','{}'));
RESET ROLE;
UPDATE public.vihem_fleet_telematics_device_assignments SET assigned_at=(SELECT stamp-interval '1 hour' FROM f) WHERE device_id=(SELECT d FROM f);
SET LOCAL ROLE service_role;
SELECT pg_temp.reject('unprovisioned device cannot ingest',format('SELECT public.vihem_fleet_ingest_position(%L::jsonb)',jsonb_build_object('imei','990000000000099','message_id','not-provisioned','recorded_at',stamp,'received_at',now(),'gps_valid',true,'latitude',57.317,'longitude',15.583,'speed_kmh',30))) FROM f;
SELECT pg_temp.reject('operator must match verified organisation',format('SELECT public.vihem_fleet_provision_device(%L,%L,%L,%L,%L)',d,o2,v,'990000000000099','Synthetic hardware evidence')) FROM f;
SELECT public.vihem_fleet_provision_device(d,o,v,'990000000000099','Synthetic hardware and SIM ownership verified in isolated QA') FROM f;
RESET ROLE;
CREATE FUNCTION pg_temp.point(seq integer,seconds integer,lat numeric,speed numeric,ignition boolean) RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_build_object('imei','990000000000099','message_id','qa:'||seq,'recorded_at',stamp+make_interval(secs=>seconds),'received_at',now(),'gps_valid',true,'latitude',lat,'longitude',15.583,'speed_kmh',speed,'heading',180,'ignition',ignition,'odometer',22140+seconds/100.0,'odometer_source','obd_measured') FROM f $$;
SET LOCAL ROLE service_role;
SELECT pg_temp.expect('first valid position stored',public.vihem_fleet_ingest_position(pg_temp.point(1,0,57.317,30,true))='stored');
SELECT pg_temp.expect('duplicate acknowledged without new row',public.vihem_fleet_ingest_position(pg_temp.point(1,0,57.317,30,true))='duplicate');
SELECT public.vihem_fleet_ingest_position(pg_temp.point(2,60,57.318,30,true));
SELECT public.vihem_fleet_ingest_position(pg_temp.point(3,120,57.319,0,false));
SELECT public.vihem_fleet_ingest_position(pg_temp.point(4,300,57.319,0,false));
SELECT pg_temp.expect('delayed sample stored as historical',public.vihem_fleet_ingest_position(pg_temp.point(5,30,57.3175,30,true))='historical');
SELECT pg_temp.reject('unknown IMEI denied',format('SELECT public.vihem_fleet_ingest_position(%L::jsonb)',pg_temp.point(8,360,57.319,0,false)||'{"imei":"990000000000098"}'::jsonb));
RESET ROLE;
SELECT pg_temp.expect('one unclassified closed trip',(SELECT count(*)=1 AND bool_and(purpose='unknown' AND ended_at IS NOT NULL AND distance_km>0 AND start_odometer_km IS NOT NULL AND end_odometer_km IS NOT NULL) FROM public.vihem_fleet_trips WHERE vehicle_id=(SELECT v FROM f)));
SET LOCAL ROLE service_role;
SELECT pg_temp.expect('same sample with different Traccar id deduplicates',public.vihem_fleet_ingest_position(pg_temp.point(1,0,57.317,30,true)||'{"message_id":"qa:new-id"}'::jsonb)='duplicate');
RESET ROLE;
SELECT pg_temp.expect('five unique positions',(SELECT count(*)=5 FROM public.vihem_fleet_telematics_readings WHERE device_id=(SELECT d FROM f)));
SELECT pg_temp.expect('OBD kilometres converted to Swedish mil',(SELECT current_odometer BETWEEN 2214 AND 2215 FROM public.vihem_fleet_vehicles WHERE id=(SELECT v FROM f)));
SELECT set_config('request.jwt.claim.sub',s::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT pg_temp.expect('staff cannot read positions or private journal',(SELECT count(*)=0 FROM public.vihem_fleet_telematics_readings) AND (SELECT count(*)=0 FROM public.vihem_fleet_trips));
SELECT pg_temp.reject('staff cannot pair',format('SELECT public.vihem_fleet_pair_device(%L,%L,%L,%L)',v,'990000000000097','FMC003','QA')) FROM f;
RESET ROLE;
SELECT set_config('request.jwt.claim.sub',x::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT pg_temp.expect('other organisation cannot read positions or journal',(SELECT count(*)=0 FROM public.vihem_fleet_telematics_readings) AND (SELECT count(*)=0 FROM public.vihem_fleet_trips));
SELECT pg_temp.reject('other organisation cannot pair existing IMEI',format('SELECT public.vihem_fleet_pair_device(%L,%L,%L,%L)',v2,'990000000000099','FMC003','QA')) FROM f;
RESET ROLE;
SELECT set_config('request.jwt.claim.sub',a::text,true) FROM f;
SET LOCAL ROLE authenticated;
SELECT pg_temp.reject('business requires purpose and driver',format('SELECT public.vihem_fleet_edit_trip(%L,1,%L,NULL,%L,%L,%L,%L)',id,'business','','','','')) FROM public.vihem_fleet_trips WHERE vehicle_id=(SELECT v FROM f);
SELECT public.vihem_fleet_edit_trip(id,1,'private',NULL,'','','','') FROM public.vihem_fleet_trips WHERE vehicle_id=(SELECT v FROM f);
SELECT pg_temp.reject('stale journal revision rejected',format('SELECT public.vihem_fleet_edit_trip(%L,1,%L,NULL,%L,%L,%L,%L)',id,'unknown','','','','')) FROM public.vihem_fleet_trips WHERE vehicle_id=(SELECT v FROM f);
SELECT public.vihem_fleet_edit_trip(id,2,'private',NULL,'','','','',22140,22141,true) FROM public.vihem_fleet_trips WHERE vehicle_id=(SELECT v FROM f);
SELECT pg_temp.expect('manual meter correction labelled',(SELECT bool_and(odometer_manual AND start_odometer_km=22140 AND end_odometer_km=22141) FROM public.vihem_fleet_trips WHERE vehicle_id=(SELECT v FROM f)));
SELECT pg_temp.reject('invalid manual meter rejected',format('SELECT public.vihem_fleet_edit_trip(%L,3,%L,NULL,%L,%L,%L,%L,100,99,true)',id,'private','','','','')) FROM public.vihem_fleet_trips WHERE vehicle_id=(SELECT v FROM f);
SELECT public.vihem_fleet_unpair_device(d) FROM f;
RESET ROLE;
SELECT pg_temp.expect('unpair retains all historical positions',(SELECT count(*)=5 FROM public.vihem_fleet_telematics_readings WHERE device_id=(SELECT d FROM f)));
SELECT pg_temp.reject('changing device organisation is forbidden',format('UPDATE public.vihem_fleet_telematics_devices SET organisation_id=%L WHERE id=%L',o2,d)) FROM f;
UPDATE public.vihem_fleet_telematics_devices SET expires_at=now()-interval '1 minute' WHERE id=(SELECT d FROM f);
SET LOCAL ROLE service_role;
SELECT pg_temp.reject('expired device rejected',format('SELECT public.vihem_fleet_ingest_position(%L::jsonb)',pg_temp.point(9,360,57.319,0,false))) FROM f;
RESET ROLE;
UPDATE public.vihem_fleet_telematics_devices SET expires_at=NULL,last_contact_at=now()-interval '10 minutes',status='online' WHERE id=(SELECT d FROM f);
SET LOCAL ROLE service_role;
SELECT public.vihem_fleet_tracking_maintenance();
RESET ROLE;
SELECT pg_temp.expect('offline status after lost mobile connection',(SELECT status='offline' FROM public.vihem_fleet_telematics_devices WHERE id=(SELECT d FROM f)));
-- Failure in event write must roll back both halves of assignment (no partial pair).
CREATE FUNCTION pg_temp.fail_event() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'QA event failure';END$$;
CREATE TRIGGER gps_qa_fail BEFORE INSERT ON public.vihem_fleet_events FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_event();
SET LOCAL ROLE authenticated;
SELECT pg_temp.reject('pair rollback on failed audit',format('SELECT public.vihem_fleet_pair_device(%L,%L,%L,%L)',v,'990000000000097','FMC003','QA')) FROM f;
RESET ROLE;
SELECT pg_temp.expect('no partial device saved',(SELECT count(*)=0 FROM public.vihem_fleet_telematics_devices WHERE imei='990000000000097'));
ROLLBACK;
